function release() external nonReentrant whenNotPaused {
        uint256 income = feeToken.balanceOf(address(this));
        if (income == 0) revert NothingToRelease();
        if (feeReceivers.length == 0) revert NoFeeReceivers();
        for (uint256 i = 0; i < feeReceivers.length; i++) {
            address feeReceiver = feeReceivers[i];
            _release(income, feeReceiver);
        }
    }

function updateBridgeableToken(address _newBridgeableToken) external restricted {
        if (bridgeableToken.balanceOf(address(this)) > 0) revert NeedToSwapAllLzTokenFirst();
        bridgeableToken = IERC20(_newBridgeableToken);
        emit BridgeableTokenUpdated(_newBridgeableToken);
    }

function _release(uint256 _totalIncomeToDistribute, address _feeReceiver) internal {
        uint256 amount = _totalIncomeToDistribute * shares[_feeReceiver] / totalShares;
        emit FeeReleasedTo(_feeReceiver, amount);
        feeToken.safeTransfer(_feeReceiver, amount);
    }

function withdraw(address _token, uint256 _amount) external nonReentrant {
        require(_amount > 0, "AMOUNT_ZERO");
        require(_token != address(0), "ZERO_ADDRESS");
        UserBalances storage user = userBalances[msg.sender];
        if (_token == address(spectral_token)) {
            require(user.spectral >= _amount, "INSUFFICIENT_BALANCE");
            user.spectral -= _amount;
        } else if (_token == address(usdc_token)) {
            require(user.usdc >= _amount, "INSUFFICIENT_BALANCE");
            user.usdc -= _amount;
        } else {
            require(
                user.agent_tokens_list[_token] >= _amount,
                "INSUFFICIENT_BALANCE"
            );
            user.agent_tokens_list[_token] -= _amount;
            if (user.agent_tokens_list[_token] == 0) {
                _removeAgentToken(user, _token);
            }
        }
        IERC20Upgradeable(_token).safeTransfer(msg.sender, _amount);
        emit Withdraw(msg.sender, _token, _amount);
    }

function withdrawAllAgentTokensByAddresses(address[] calldata tokens) external nonReentrant {
        for (uint256 i = 0; i < tokens.length; i++) {
            uint256 amount = userBalances[msg.sender].agent_tokens_list[tokens[i]];
            require(amount > 0, "AMOUNT_ZERO");
            userBalances[msg.sender].agent_tokens_list[tokens[i]] = 0;
            _removeAgentToken(userBalances[msg.sender], tokens[i]);
            IERC20Upgradeable(tokens[i]).safeTransfer(msg.sender, amount);
            emit Withdraw(msg.sender, tokens[i], amount);
        }
    }

function decimals() external view override returns (uint8) {
        return _aggregator.decimals();
    }

function _getLatestRoundData()
        private
        view
        returns (
            uint80,
            uint256 finalPrice,
            uint256
        )
    {
        (uint80 round, int256 latestPrice, , uint256 latestTimestamp, ) = _aggregator.latestRoundData();
        finalPrice = uint256(latestPrice);
        // SWC-104-Unchecked Call Return Value: L96 -L100
        if (latestPrice < 0) {
            _requireEnoughHistory(round);
            (round, finalPrice, latestTimestamp) = _getRoundData(round - 1);
        }
        return (round, finalPrice, latestTimestamp);
    }

function _getRoundData(uint80 _round)
        private
        view
        returns (
            uint80,
            uint256,
            uint256
        )
    {
        (uint80 round, int256 latestPrice, , uint256 latestTimestamp, ) = _aggregator.getRoundData(_round);
        while (latestPrice < 0) {
            _requireEnoughHistory(round);
            round = round - 1;
            (, latestPrice, , latestTimestamp, ) = _aggregator.getRoundData(round);
        }
        return (round, uint256(latestPrice), latestTimestamp);
    }

function getReferenceData() internal view returns (IStdReference.ReferenceData memory) {
        IStdReference.ReferenceData memory bandData = stdRef.getReferenceData(baseAsset, QUOTE_ASSET);
        // BPF_TQZ: timestamp for quote is zero
        require(bandData.lastUpdatedQuote > 0, "BPF_TQZ");
        // BPF_TBZ: timestamp for base is zero
        require(bandData.lastUpdatedBase > 0, "BPF_TBZ");
        // BPF_IP: invalid price
        require(bandData.rate > 0, "BPF_IP");

        return bandData;
    }

function _getSqrtMarkTwapX96(uint32 twapInterval) internal view returns (uint160) {
        // return the current price as twapInterval is too short/ meaningless
        if (twapInterval < 10) {
            (uint160 sqrtMarkPrice, , , , , , ) = IUniswapV3Pool(pool).slot0();
            return sqrtMarkPrice;
        }
        uint32[] memory secondsAgos = new uint32[](2);

        // solhint-disable-next-line not-rely-on-time
        secondsAgos[0] = twapInterval;
        secondsAgos[1] = 0;
        (int56[] memory tickCumulatives, ) = IUniswapV3Pool(pool).observe(secondsAgos);

        // tick(imprecise as it's an integer) to price
        return TickMath.getSqrtRatioAtTick(int24((tickCumulatives[1] - tickCumulatives[0]) / twapInterval));
    }

function balanceOfy3CRV() public view returns (uint256) {
        return IERC20(y3crv).balanceOf(address(this));
    }

function balanceOfy3CRVinWant() public view returns (uint256) {
        return balanceOfy3CRV()
                .mul(yvERC20(y3crv).getPricePerFullShare()).div(1e18)
                .mul(ICurveFi(_3pool).get_virtual_price()).div(1e30);
    }

function prepareReturn(uint256 _debtOutstanding)
        internal
        override
        returns (
            uint256 _profit,
            uint256 _loss,
            uint256 _debtPayment
        )
    {
        _profit = want.balanceOf(address(this));
        uint256 _p = yvERC20(y3crv).getPricePerFullShare();
        _p = _p.mul(ICurveFi(_3pool).get_virtual_price()).div(1e18);
        if (_p >= p) {
            _profit = _profit.add((_p.sub(p)).mul(balanceOfy3CRV()).div(1e30));
        }
        else {
            _loss = (p.sub(_p)).mul(balanceOfy3CRV()).div(1e30);
        }
        p = _p;

        if (_debtOutstanding > 0) {
            _debtPayment = liquidatePosition(_debtOutstanding);
        }
    }

function _deposit() internal {
        uint256 _want = (want.balanceOf(address(this))).sub(tank);
        if (_want > 0) {
            uint256 v = _want.mul(1e30).div(ICurveFi(_3pool).get_virtual_price());
            ICurveFi(_3pool).add_liquidity([0, 0, _want], v.mul(DENOMINATOR.sub(slip)).div(DENOMINATOR));
        }
        uint256 _bal = IERC20(_3crv).balanceOf(address(this));
        if (_bal > 0) {
            yvERC20(y3crv).deposit(_bal);
        }
    }

function _withdrawAll() internal {
        uint256 _y3crv = IERC20(y3crv).balanceOf(address(this));
        if (_y3crv > 0) {
            yvERC20(y3crv).withdraw(_y3crv);
            _withdrawOne(IERC20(_3crv).balanceOf(address(this)));
        }
    }

function _withdrawOne(uint256 _amnt) internal returns (uint256) {
        uint256 _before = want.balanceOf(address(this));
        ICurveFi(_3pool).remove_liquidity_one_coin(_amnt, 2, _amnt.mul(DENOMINATOR.sub(slip)).div(DENOMINATOR).div(1e12));
        uint256 _after = want.balanceOf(address(this));

        return _after.sub(_before);
    }

function liquidatePosition(uint256 _amountNeeded)
        internal
        override
        returns (uint256 _amountFreed)
    {
        uint256 _balance = want.balanceOf(address(this));
        if (_balance < _amountNeeded) {
            _amountFreed = _withdrawSome(_amountNeeded.sub(_balance));
            _amountFreed = _amountFreed.add(_balance);
            tank = 0;
        }
        else {
            _amountFreed = _amountNeeded;
            if (tank >= _amountNeeded) tank = tank.sub(_amountNeeded);
            else tank = 0;
        }
    }

function _withdrawSome(uint256 _amount) internal returns (uint256) {
        uint256 _amnt = _amount.mul(1e30).div(ICurveFi(_3pool).get_virtual_price());
        uint256 _amt = _amnt.mul(1e18).div(yvERC20(y3crv).getPricePerFullShare());
        uint256 _bal = IERC20(y3crv).balanceOf(address(this));
        if (_amt > _bal) _amt = _bal;
        uint256 _before = IERC20(_3crv).balanceOf(address(this));
        yvERC20(y3crv).withdraw(_amt);
        uint256 _after = IERC20(_3crv).balanceOf(address(this));
        return _withdrawOne(_after.sub(_before));
    }

function prepareMigration(address _newStrategy) internal override {
        IERC20(y3crv).safeTransfer(_newStrategy, IERC20(y3crv).balanceOf(address(this)));
        IERC20(_3crv).safeTransfer(_newStrategy, IERC20(_3crv).balanceOf(address(this)));
    }

function tick() public view returns (uint256 _t, uint256 _c) {
        _t = ICurveFi(_3pool).balances(2).mul(threshold).div(DENOMINATOR);
        _c = balanceOfy3CRVinWant();
    }

function rebalance() public {
        (uint256 _t, uint256 _c) = tick();
        if (_c > _t) {
            _withdrawSome(_c.sub(_t));
            tank = want.balanceOf(address(this));
        }
    }

function forceD(uint256 _amount) external onlyAuthorized {
        uint256 v = _amount.mul(1e30).div(ICurveFi(_3pool).get_virtual_price());
        ICurveFi(_3pool).add_liquidity([0, 0, _amount], v.mul(DENOMINATOR.sub(slip)).div(DENOMINATOR));
        if (_amount < tank) tank = tank.sub(_amount);
        else tank = 0;

        uint256 _bal = IERC20(_3crv).balanceOf(address(this));
        yvERC20(y3crv).deposit(_bal);
    }

function forceW(uint256 _amt) external onlyAuthorized {
        uint256 _before = IERC20(_3crv).balanceOf(address(this));
        yvERC20(y3crv).withdraw(_amt);
        uint256 _after = IERC20(_3crv).balanceOf(address(this));
        _amt = _after.sub(_before);

        _before = want.balanceOf(address(this));
        ICurveFi(_3pool).remove_liquidity_one_coin(_amt, 2, _amt.mul(DENOMINATOR.sub(slip)).div(DENOMINATOR).div(1e12));
